mkdir -p /tmp/bt && cat > /tmp/bt/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { spawnSync, spawn } from 'node:child_process';
const botPath = process.argv[2];
const sd = process.env.STATE_DIR;
const { recordEvent, checkEmail } = await import(botPath);
const now = new Date();
const c = (email, kind='marketing') => checkEmail({ email, kind, now });
assert.deepEqual(await c('<EMAIL>'), { allowed: true, rule: '' });
await recordEvent({ email: '<EMAIL>', type: 'unsubscribe', now });
for (const v of ['<EMAIL>', '  <EMAIL> ', 'Alice <<EMAIL>>', 'mailto:<EMAIL>', '<EMAIL>.', '<EMAIL>', '"alice"@x.com'])
  assert.equal((await c(v)).rule, 'unsubscribed', v);
assert.deepEqual(await c('<EMAIL>', 'transactional'), { allowed: true, rule: '' });
assert.equal((await c('<EMAIL>')).allowed, true);
await recordEvent({ email: '<EMAIL>', type: 'spam_complaint', now });
assert.equal((await c('<EMAIL>')).rule, 'spam_complaint');
assert.equal((await c('<EMAIL>', 'transactional')).allowed, true);
await recordEvent({ email: '<EMAIL>', type: 'hard_bounce', now });
assert.equal((await c('<EMAIL>', 'transactional')).rule, 'hard_bounce');
assert.equal((await c('<EMAIL>')).allowed, true);
assert.equal((await c('nonsense')).rule, 'invalid_address');
assert.equal((await c('<EMAIL>', 'promo')).rule, 'invalid_kind');
await assert.rejects(recordEvent({ email: '<EMAIL>', type: 'x', now }));
// concurrent writers in separate processes
const code = `import {recordEvent} from ${JSON.stringify(botPath)};
await Promise.all([...Array(20)].map((_,i)=>recordEvent({email:'U'+(i%5)+'@c.com',type:'unsubscribe',now:new Date()})));`;
await Promise.all([...Array(8)].map(() => new Promise((res, rej) => {
  const p = spawn('node', ['--input-type=module', '-e', code], { stdio: 'inherit' });
  p.on('exit', k => k ? rej(new Error('child fail')) : res());
})));
// fresh process = restart
const r = spawnSync('node', ['--input-type=module', '-e', `import {checkEmail} from ${JSON.stringify(botPath)};
const out=[];for(let i=0;i<5;i++)out.push((await checkEmail({email:'u'+i+'@c.com',kind:'marketing',now:new Date()})).rule);
console.log(out.join())`], { encoding: 'utf8' });
assert.equal(r.stdout.trim(), 'unsubscribed,'.repeat(4) + 'unsubscribed');
console.log('ok');
EOF
cd /tmp/bt && STATE_DIR=$(mktemp -d)/s node test.mjs <HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/courier-d4-2/bot.mjs
